)

# Find the document with the most number of sections
result = document.WHERE(
    HAS(document_section) == 1
).CALCULATE(
    document_name=document_name,
    section_count=COUNT(document_section)
).TOP_K(1, by=(section_count.DESC(), document_code.ASC())).CALCULATE(
    document_name=document_name
)

most_reviewed_movie = ratings.CALCULATE(
    movie_title=movie.title
).PARTITION(name="movie_groups", by=movie_title).CALCULATE(
    movie_title=movie_title,
    review_count=COUNT(ratings)
).TOP_K(1, by=review_count.DESC())

most_rated_movie = ratings.CALCULATE(
    movie_title=movie.title,
    movie_id=movie.mid
).PARTITION(name="movie_groups", by=(movie_title, movie_id)).CALCULATE(
    title=movie_title,
    mID=movie_id,
    rating_count=COUNT(ratings)
).TOP_K(1, by=(rating_count.DESC(), mID.DESC())).CALCULATE(
    title=title
)

youngest_captain_ship = captains.CALCULATE(
    age_numeric=CAST(age, "INTEGER")
).TOP_K(1, by=age_numeric.ASC()).CALCULATE(
    ship_name=ship.name
)

# Find the oldest technician and get their starting year
oldest_technician_starting_year = technician.WHERE(
    age == MAX(technician.age)
).CALCULATE(
    starting_year=starting_year
).SINGULAR().starting_year

# Find the wrestler with the most days held among those who were eliminated
result = wrestlers.WHERE(
    HAS(eliminations) == 1
).TOP_K(1, by=CAST(days_held, "INTEGER").DESC()).eliminations.SINGULAR().CALCULATE(
    elimination_time=time
)

total_non_brown_savings = saving.WHERE(account.name != "Brown").CALCULATE(
    total_balance=SUM(balance)
)

# Find countries that do not use English and sum their populations
non_english_countries_population = countries.WHERE(
    HASNOT(countrylanguages.WHERE(language == "English"))
).CALCULATE(
    total_population = SUM(population)
).total_population

# Count people who have no friends living in Austin
result = people.WHERE(
    HASNOT(personfriends.WHERE(person.city == "Austin")) == 1
).CALCULATE(
    total_count = COUNT(people)
)

# Calculate total quantity of products in cancelled orders
cancelled_order_products = customer_order.WHERE(
    order_status == "Cancelled"
).CALCULATE(
    total_products = SUM(CAST(order_item.order_quantity, "INTEGER"))
)

# Filter countries founded before 1930, get their official languages, and count unique ones globally
unique_official_languages_count = world_1.CALCULATE(
    total_unique_official_languages=NDISTINCT(
        countries.WHERE(indepyear < 1930).countrylanguages.WHERE(isofficial == "T").language
    )
)

# Calculate the average city area across all districts and filter districts with above-average area
result = store_product.GRAPH.CALCULATE(
    avg_city_area=AVG(store_product.districts.city_area)
).store_product.districts.WHERE(
    city_area > avg_city_area
).CALCULATE(
    total_population=SUM(city_population)
)

# Filter manufacturers with headquarters in Tokyo or Taiwan and calculate total revenue
result = manufacturer.WHERE(
    (headquarter == "Tokyo") | (headquarter == "Taiwan")
).CALCULATE(
    total_revenue = SUM(revenue)
)

most_enrolled_course = course.WHERE(
    HAS(student_enrolment_course) == 1
).CALCULATE(
    course_name=course_name,
    enrollment_count=COUNT(student_enrolment_course)
).ORDER_BY(
    enrollment_count.DESC(),
    course_name.ASC()
).TOP_K(1, by=enrollment_count.DESC()).CALCULATE(
    course_name=course_name
)

airlines_with_many_flights = flight.PARTITION(
    name="airline_groups", 
    by=airline
).WHERE(
    COUNT(flight) >= 10
).CALCULATE(
    airline_name=airline.airline
)

# Find catalog contents with length below 3 or above 5
catalog_entries_filtered = catalog_content.WHERE(
    (length < "3") | (length > "5")
).CALCULATE(
    catalog_entry_name=catalog_entry_name
)

cities_with_temp_conditions = temperatures.WHERE(
    (mar < jul) | (mar > oct)
).CALCULATE(
    city_name=city.city
)

# Filter elections for Democratic and Liberal parties by joining with parties table
relevant_elections = election.elections.WHERE(
    (party_join.party == "Democratic") | (party_join.party == "Liberal")
)

# Group by committee and find committees with both parties represented
committees_with_both_parties = relevant_elections.PARTITION(
    name="committee_groups", 
    by=committee
).WHERE(
    NDISTINCT(elections.party_join.party) == 2
).CALCULATE(
    committee_name=committee
)

countries_with_english_or_dutch = countrylanguages.WHERE(
    ISIN(language, ("English", "Dutch")) & 
    (isofficial == "T")
).CALCULATE(
    country_name=country.name
)

# Find the minimum surface area among European countries
european_min_area = countries.WHERE(continent == "Europe").CALCULATE(
    min_area = MIN(surfacearea)
)

# Find countries with area greater than any European country (i.e., greater than the smallest European country)
result = countries.WHERE(
    surfacearea > european_min_area.SINGULAR().min_area
).CALCULATE(
    name
)

# Find the minimum dew point value in zip code 94107
threshold_result = bike_1.weathers.WHERE(zip_code == 94107).CALCULATE(
    min_threshold=MIN(min_dew_point_f)
)

# Find all weather records with minimum dew point smaller than the threshold
result = bike_1.CALCULATE(
    threshold_value=threshold_result.min_threshold.SINGULAR()
).weathers.WHERE(
    min_dew_point_f < threshold_value
).CALCULATE(
    date=date,
    zip_code=zip_code
).ORDER_BY(date.ASC(), zip_code.ASC())

# Find films with rental rate 0.99 that have inventory records and less than 3 copies
film_inventory = films.WHERE(
    rental_rate == 0.99
).inventories.PARTITION(
    name="film_groups", by=film_id
).WHERE(
    COUNT(inventories) < 3
).CALCULATE(
    film_id=film_id,
    title=film.title
)

makers_with_many_models = car_maker.WHERE(
    COUNT(model_lists) > 3
).CALCULATE(
    maker_id=id,
    maker_fullname=fullname
)

most_frequent_program = broadcasts.PARTITION(
    name="program_groups", by=program_id
).CALCULATE(
    broadcast_count=COUNT(broadcasts),
    program_name=broadcasts.program.name
).TOP_K(1, by=broadcast_count.DESC()).CALCULATE(
    program_name=program_name
)

most_frequent_visitor = students.WHERE(
    HAS(visits_restaurants)
).CALCULATE(
    visit_count=COUNT(visits_restaurants),
    first_name=fname,
    last_name=lname
).TOP_K(1, by=visit_count.DESC()).CALCULATE(
    first_name=first_name,
    last_name=last_name
)

# Count students living in NYC who have class senator votes in spring election cycle
result = students.WHERE(
    (city_code == "NYC") &
    HAS(voting_records.WHERE(
        (election_cycle == "spring") &
        (class_senator_vote != None)
    ))
).CALCULATE(
    student_count = COUNT(stuid)
)

# Find advisors for students who received treasurer votes in spring election cycle
spring_treasurer_votes = voting_records.WHERE(
    (election_cycle == "Spring") & 
    (treasurer_vote != None)
)

# Get the candidates who received treasurer votes and their advisor info
advisor_ids = spring_treasurer_votes.CALCULATE(
    candidate_id = treasurer_vote
).PARTITION(name="candidates", by=candidate_id).students.WHERE(
    stuid == candidate_id
).CALCULATE(
    advisor_id = advisor
).PARTITION(name="unique_advisors", by=advisor_id).CALCULATE(
    advisor_id = advisor_id
)

# Get average salary by department for employees with commission
avg_salary_by_dept = employee.WHERE(
    COMMISSION_PCT != "null"
).PARTITION(
    name="dept_groups", 
    by=DEPARTMENT_ID
).CALCULATE(
    DEPARTMENT_ID=DEPARTMENT_ID,
    avg_salary=AVG(SALARY)
)

# Count crimes that are still under investigation
crimes_under_investigation_count = GreaterManchesterCrime.WHERE(
    outcome == "Under investigation"
).CALCULATE(
    total_count = COUNT(crimeid)
)

drug_crimes_count = GreaterManchesterCrime.WHERE(type == "Drugs").CALCULATE(
    total_drug_crimes=COUNT(GreaterManchesterCrime.crimeid)
)

# Count papers published in VLDB conference after 2000
vldb_papers_after_2000 = publications.WHERE(
    HAS(conference) == 1
).WHERE(
    conference.name == "VLDB"
).WHERE(
    year > 2000
).CALCULATE(
    count_papers = COUNT(publications)
)

# Find publications in PVLDB journal from 2005 and sum their citations
pvldb_2005_citations = academic.CALCULATE(
    total_citations = SUM(
        publications.WHERE(
            (journal.name == "PVLDB") & 
            (year == "2005")
        ).CALCULATE(citation_as_int = CAST(citation_num, "int")).citation_as_int
    )
)

# Find the CrimeID of the last instance of a violent or sexual offense
last_violent_sexual_offense = GreaterManchesterCrime.WHERE(
    Type == "Violence and sexual offences"
).TOP_K(1, by=CrimeTS.DESC()).CALCULATE(
    CrimeID
)
